; ---- Subroutine: math.crc16 ----
    ALIGN 2

math.crc16:
            move.w  d3,-(sp)
            move.w  d4,-(sp)
            lea     math.crc16_table,a1
            move.w  d1,d3           ; running crc = initvalue
.loop:
            subq.w  #1,d0
            bcs     .done
            move.w  d3,d1           ; copy crc
            lsr.w   #8,d1           ; index high byte
            move.b  (a0)+,d4        ; next data byte
            eor.b   d4,d1           ; table index
            lsl.w   #8,d3           ; crc <<= 8
            and.w   #$ff,d1
            add.w   d1,d1           ; word index
            move.w  (a1,d1.w),d1
            eor.w   d1,d3           ; update crc
            bra     .loop
.done:
            move.w  d3,d0
            eor.w   d2,d0           ; apply xorout
            move.w  (sp)+,d4
            move.w  (sp)+,d3
            rts
; End of subroutine: math.crc16

; ---- Subroutine: math.crc16_start ----
; source: shared_m68k_math.p8:667

    ALIGN 2

math.crc16_start:
        ; loadm.w r783.w,[math.crc16_start.initvalue]
    move.w  math.crc16_start.initvalue,p8_regfile+1842
        ; storem.w r783.w,[math.crc16_state]
    move.w  p8_regfile+1842,math.crc16_state
        ; return
    rts
; End of subroutine: math.crc16_start


; ---- Subroutine: math.crc16_update ----
    ALIGN 2

math.crc16_update:
            lea     math.crc16_table,a0
            move.w  math.crc16_state,d1
            lsr.w   #8,d1           ; high byte of crc
            eor.b   d0,d1           ; table index
            move.w  math.crc16_state,d0
            lsl.w   #8,d0           ; crc <<= 8
            and.w   #$ff,d1
            add.w   d1,d1           ; word index
            move.w  (a0,d1.w),d1
            eor.w   d1,d0           ; new crc
            move.w  d0,math.crc16_state
            rts
; End of subroutine: math.crc16_update

; ---- Subroutine: math.crc16_end ----
; source: shared_m68k_math.p8:691

    ALIGN 2

math.crc16_end:
        ; loadm.w r784.w,[math.crc16_state]
    move.w  math.crc16_state,p8_regfile+1844
        ; loadm.w r785.w,[math.crc16_end.xorout]
    move.w  math.crc16_end.xorout,p8_regfile+1846
        ; xorr.w r784.w,r785.w
    move.w  p8_regfile+1846,d0
    eor.w  d0,p8_regfile+1844
        ; returnr.w r784.w
    move.w  p8_regfile+1844,d0
    rts
; End of subroutine: math.crc16_end


; ---- Subroutine: math.crc32 ----
    ALIGN 2

math.crc32:
            move.l  d2,-(sp)
            lea     math.crc32_table,a1
            move.l  #$ffffffff,d1   ; running crc
.loop:
            subq.w  #1,d0
            bcs     .done
            move.b  (a0)+,d2        ; next data byte
            eor.b   d1,d2           ; table index = (crc ^ byte) & $ff
            lsr.l   #8,d1           ; crc >>= 8
            and.l   #$ff,d2
            lsl.l   #2,d2           ; long index
            move.l  (a1,d2.l),d2
            eor.l   d2,d1           ; update crc
            bra     .loop
.done:
            move.l  d1,d0
            eor.l   #$ffffffff,d0   ; final xor
            move.l  (sp)+,d2
            rts
; End of subroutine: math.crc32

; ---- Subroutine: math.crc32_start ----
; source: shared_m68k_math.p8:722

    ALIGN 2

math.crc32_start:
        ; storeim.l #-1.l,[math.crc32_state]
    move.l  #-1,math.crc32_state
        ; return
    rts
; End of subroutine: math.crc32_start


; ---- Subroutine: math.crc32_update ----
    ALIGN 2

math.crc32_update:
            lea     math.crc32_table,a0
            move.l  math.crc32_state,d1
            eor.b   d1,d0           ; table index = (crc ^ byte) & $ff
            lsr.l   #8,d1           ; crc >>= 8
            and.l   #$ff,d0
            lsl.l   #2,d0           ; long index
            move.l  (a0,d0.l),d0
            eor.l   d0,d1           ; new crc
            move.l  d1,math.crc32_state
            rts
; End of subroutine: math.crc32_update

; ---- Subroutine: math.crc32_end ----
; source: shared_m68k_math.p8:744

    ALIGN 2

math.crc32_end:
        ; loadm.l r786.l,[math.crc32_state]
    move.l  math.crc32_state,p8_regfile+1848
        ; xor.l r786.l,#-1.l
    eori.l  #-1,p8_regfile+1848
        ; returnr.l r786.l
    move.l  p8_regfile+1848,d0
    rts
; End of subroutine: math.crc32_end


; Block: qemu

qemu:

; ---- Subroutine: qemu.chrout ----
    ALIGN 2

qemu.chrout:
            move.l  d0,qemu.TTY_PUT_CHAR
            rts
; End of subroutine: qemu.chrout


; ---- Subroutine: qemu.chrin ----
    ALIGN 2

qemu.chrin:
            suba.l  #4,sp
            movea.l  sp,a0       ; buffer = stack pointer (in A0 for input_data)
            moveq   #1,d1        ; maxlen = 1
            bsr     qemu.input_data
            move.b  (sp),d0
            adda.l  #4,sp
            rts
; End of subroutine: qemu.chrin


; ---- Subroutine: qemu.keypressed ----
    ALIGN 2

qemu.keypressed:
            movea.l #qemu.TTY_BYTES_READY,a1
            move.l  (a1),d0
            tst.l   d0
            rts
; End of subroutine: qemu.keypressed


; ---- Subroutine: qemu.input_data ----
    ALIGN 2

qemu.input_data:
1$:         movea.l  #qemu.TTY_BYTES_READY,a1
            move.l   (a1),d0
            tst.l    d0
            beq      1$                  ; wait for at least 1 byte
            ; d0 = available bytes, d1 = maxlen
            cmp.l    d1,d0               ; available - maxlen
            bls      2$                  ; if available <= maxlen, keep d0
            move.l   d1,d0               ; else cap at maxlen
2$:         movea.l  #qemu.TTY_DATA_PTR,a1
            move.l   a0,(a1)
            movea.l  #qemu.TTY_DATA_LEN,a1
            move.l   d0,(a1)
            movea.l  #qemu.TTY_CMD,a1
            move.l   #qemu.TTY_CMD_READ_BUFFER,(a1)
            rts
; End of subroutine: qemu.input_data


; ---- Subroutine: qemu.puts ----
    ALIGN 2

qemu.puts:
            move.l  d0,-(sp)
            move.l  a0,-(sp)
.loop:
            move.b   (a0)+,d0
            beq      .done
            move.l   d0,qemu.TTY_PUT_CHAR
            bra.s    .loop
.done:
            move.l  (sp)+,a0
            move.l  (sp)+,d0
            rts
; End of subroutine: qemu.puts

